package com.Polarice3.Goety.common.blocks.entities;

import com.Polarice3.Goety.api.blocks.entities.IWaystoneBlock;
import com.Polarice3.Goety.api.magic.GolemType;
import com.Polarice3.Goety.common.blocks.AnimatorBlock;
import com.Polarice3.Goety.common.blocks.ModBlocks;
import com.Polarice3.Goety.common.entities.ModEntityType;
import com.Polarice3.Goety.common.entities.ally.undead.HauntedArmorServant;
import com.Polarice3.Goety.common.entities.deco.HauntedArmorStand;
import com.Polarice3.Goety.common.items.ModItems;
import com.Polarice3.Goety.common.items.WaystoneItem;
import com.Polarice3.Goety.common.magic.construct.SpawnFromBlock;
import com.Polarice3.Goety.common.research.ResearchList;
import com.Polarice3.Goety.config.MainConfig;
import com.Polarice3.Goety.init.ModSounds;
import com.Polarice3.Goety.utils.ItemHelper;
import com.Polarice3.Goety.utils.SEHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.GlobalPos;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.Clearable;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.HumanoidArm;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;

import javax.annotation.Nullable;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

public class AnimatorBlockEntity extends BlockEntity implements IWaystoneBlock, Clearable {
    private ItemStack item = ItemStack.EMPTY;
    private CursedCageBlockEntity cursedCageTile;
    private int spinning;
    public boolean showBlock;

    public AnimatorBlockEntity(BlockPos blockPos, BlockState blockState) {
        super(ModBlockEntities.ANIMATOR.get(), blockPos, blockState);
    }

    public int getSoulCost(){
        if (this.getPosition() != null){
            double distance = this.getBlockPos().distToCenterSqr(this.getPosition().pos().getCenter());
            return (int) (MainConfig.AnimatorCost.get() * distance);
        }
        return 0;
    }

    @Override
    public AABB getRenderBoundingBox() {
        return BlockEntity.INFINITE_EXTENT_AABB;
    }

    public void summonGolem(){
        if (this.level != null) {
            if (this.getPosition() != null) {
                if (this.level.dimension() == this.getPosition().dimension()) {
                    if (this.level.isLoaded(this.getPosition().pos())) {
                        if (this.checkCage() && this.cursedCageTile.getSouls() >= this.getSoulCost()) {
                            ItemStack itemStack = ModItems.ANIMATION_CORE.get().getDefaultInstance();
                            BlockState blockState = this.level.getBlockState(this.getPosition().pos());
                            AABB aabb = new AABB(this.getPosition().pos());
                            List<HauntedArmorStand> list = this.level.getEntitiesOfClass(HauntedArmorStand.class, aabb, ItemHelper::isFullEquipped);
                            Optional<HauntedArmorStand> optional = !list.isEmpty() ? list.stream().findFirst() : Optional.empty();
                            if (optional.isPresent() && SEHelper.hasResearch(this.getOwner(), ResearchList.HAUNTING)){
                                HauntedArmorStand hauntedArmorStand = optional.get();
                                HauntedArmorServant hauntedArmorServant = new HauntedArmorServant(ModEntityType.HAUNTED_ARMOR_SERVANT.get(), this.level);
                                for (EquipmentSlot equipmentSlot : EquipmentSlot.values()) {
                                    hauntedArmorServant.setItemSlot(equipmentSlot, hauntedArmorStand.getItemBySlot(equipmentSlot));
                                    hauntedArmorServant.setGuaranteedDrop(equipmentSlot);
                                }
                                hauntedArmorServant.setPersistenceRequired();
                                hauntedArmorServant.setTrueOwner(this.getOwner());
                                hauntedArmorServant.moveTo(hauntedArmorStand.blockPosition(), hauntedArmorStand.getYRot(), hauntedArmorStand.getXRot());
                                hauntedArmorServant.setLeftHanded(this.getOwner().getMainArm() == HumanoidArm.LEFT);
                                if (this.level.addFreshEntity(hauntedArmorServant)) {
                                    hauntedArmorStand.playSound(ModSounds.SUMMON_SPELL.get());
                                    hauntedArmorStand.showBreakingParticles();
                                    hauntedArmorStand.discard();
                                }
                            } else if (GolemType.getGolemList().containsKey(blockState)) {
                                if (GolemType.getGolemList().get(blockState).spawnServant(this.getOwner(), itemStack, this.level, this.getPosition().pos())) {
                                    this.level.playSound(null, this.getBlockPos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    this.level.playSound(null, this.getPosition().pos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    this.cursedCageTile.decreaseSouls(this.getSoulCost());
                                    this.generateManyParticles();
                                }
                            } else {
                                if (SpawnFromBlock.spawnServant(this.getOwner(), itemStack, this.level, this.getPosition().pos())) {
                                    this.level.playSound(null, this.getBlockPos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    this.level.playSound(null, this.getPosition().pos(), ModSounds.SUMMON_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    this.cursedCageTile.decreaseSouls(this.getSoulCost());
                                    this.generateManyParticles();
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    public ItemStack getItem() {
        return this.item;
    }

    public void setItem(ItemStack stack) {
        this.item = stack;
        this.markUpdated();
    }

    public Player getOwner(){
        if (this.level != null) {
            if (!this.getItem().isEmpty()) {
                if (this.getItem().getItem() instanceof WaystoneItem && this.getItem().getTag() != null) {
                    if (this.getItem().getTag().contains(WaystoneItem.TAG_OWNER)) {
                        UUID owner = this.getItem().getTag().getUUID(WaystoneItem.TAG_OWNER);
                        return this.level.getPlayerByUUID(owner);
                    }
                }
            }
        }
        return null;
    }

    @Nullable
    public GlobalPos getPosition(){
        if (!this.getItem().isEmpty()) {
            if (this.getItem().getTag() != null) {
                return WaystoneItem.getPosition(this.getItem().getTag());
            }
        }
        return null;
    }

    public int getSpinning(){
        return this.spinning;
    }

    public void tick() {
        if (this.spinning > 0){
            --this.spinning;
        }
        if (this.level != null) {
            this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(AnimatorBlock.POWERED, this.checkCage() && this.getPosition() != null), 3);
        }
    }

    public void generateManyParticles(){
        BlockPos blockpos = this.getBlockPos();
        if (this.level != null) {
            if (!this.level.isClientSide) {
                ServerLevel serverWorld = (ServerLevel) this.level;
                for(int k = 0; k < 20; ++k) {
                    double d9 = (double)blockpos.getX() + 0.5D + (this.level.random.nextDouble() - 0.5D) * 2.0D;
                    double d13 = (double)blockpos.getY() + 0.5D + (this.level.random.nextDouble() - 0.5D) * 2.0D;
                    double d19 = (double)blockpos.getZ() + 0.5D + (this.level.random.nextDouble() - 0.5D) * 2.0D;
                    serverWorld.sendParticles(ParticleTypes.SMOKE, d9, d13, d19, 1, 0.0D, 0.0D, 0.0D, 0);
                    serverWorld.sendParticles(ParticleTypes.FLAME, d9, d13, d19, 1, 0.0D, 0.0D, 0.0D, 0);
                }
            }
        }

    }

    private boolean checkCage() {
        if (this.level != null) {
            BlockPos pos = new BlockPos(this.getBlockPos().getX(), this.getBlockPos().getY() - 1, this.getBlockPos().getZ());
            BlockState blockState = this.level.getBlockState(pos);
            if (blockState.is(ModBlocks.CURSED_CAGE_BLOCK.get())) {
                BlockEntity tileentity = this.level.getBlockEntity(pos);
                if (tileentity instanceof CursedCageBlockEntity cageBlock) {
                    this.cursedCageTile = cageBlock;
                    return !cursedCageTile.getItem().isEmpty();
                }
            }
        }
        return false;
    }

    public boolean isShowBlock(){
        return this.showBlock;
    }

    public void setShowBlock(boolean showBlock){
        this.showBlock = showBlock;
        this.markUpdated();
    }

    public void markNetworkDirty() {

    }

    @Override
    public CompoundTag getUpdateTag() {
        return this.writeNetwork(super.getUpdateTag());
    }

    @Override
    public void onDataPacket(Connection net, ClientboundBlockEntityDataPacket pkt) {
        this.readNetwork(pkt.getTag());
    }

    @Override
    public void handleUpdateTag(CompoundTag tag) {
        super.load(tag);
        this.readNetwork(tag);
    }

    public void readNetwork(CompoundTag tag) {
        this.item = ItemStack.of(tag.getCompound("item"));
        if (tag.contains("showBlock")) {
            this.showBlock = tag.getBoolean("showBlock");
        }
    }

    public CompoundTag writeNetwork(CompoundTag tag) {
        tag.put("item", item.save(new CompoundTag()));
        tag.putBoolean("showBlock", this.showBlock);
        return tag;
    }

    public void clearContent() {
        this.setItem(ItemStack.EMPTY);
    }

    public void markUpdated() {
        this.setChanged();
        if (this.level != null) {
            this.level.sendBlockUpdated(this.worldPosition, this.getBlockState(), this.getBlockState(), 3);
        }
    }

    @Override
    public void load(CompoundTag compound) {
        this.readNetwork(compound);
        super.load(compound);
    }

    @Override
    public void saveAdditional(CompoundTag compound) {
        this.writeNetwork(compound);
        super.saveAdditional(compound);
    }

    @Override
    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }
}

package com.Polarice3.Goety.common.blocks.entities;

import com.Polarice3.Goety.api.items.magic.ITotem;
import com.Polarice3.Goety.common.items.ModItems;
import com.Polarice3.Goety.utils.SEHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.Clearable;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import java.util.UUID;

public class CursedCageBlockEntity extends BlockEntity implements Clearable {
    private ItemStack item = ItemStack.EMPTY;
    private int spinning;

    public CursedCageBlockEntity(BlockPos blockPos, BlockState blockState) {
        super(ModBlockEntities.CURSED_CAGE.get(), blockPos, blockState);
    }

    @Override
    public void load(CompoundTag compound) {
        this.readNetwork(compound);
        super.load(compound);
    }

    @Override
    public void saveAdditional(CompoundTag compound) {
        this.writeNetwork(compound);
        super.saveAdditional(compound);
    }

    @Override
    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    public ItemStack getItem() {
        return this.item;
    }

    public void setItem(ItemStack stack) {
        this.item = stack;
        this.setChanged();
    }

    public Player getOwner(){
        if (this.item.getItem() == ModItems.SOUL_TRANSFER.get() && this.item.getTag() != null) {
            if (this.item.getTag().contains("owner")) {
                UUID owner = this.item.getTag().getUUID("owner");
                if (this.level instanceof ServerLevel serverLevel) {
                    return serverLevel.getServer().getPlayerList().getPlayer(owner);
                } else if (this.level != null) {
                    return this.level.getPlayerByUUID(owner);
                }
            }
        }
        return null;
    }

    public int getSouls(){
        if (this.level != null) {
            Player player = this.getOwner();
            if (player != null) {
                if (SEHelper.getSEActive(player)) {
                    int souls = SEHelper.getSESouls(player);
                    if (souls > 0) {
                        return souls;
                    }
                }
            }
            if (this.item.getItem() instanceof ITotem) {
                if (this.item.getTag() != null) {
                    return this.item.getTag().getInt(ITotem.SOULS_AMOUNT);
                }
            }
        }
        return 0;
    }

    public void decreaseSouls(int souls) {
        if (this.item.getItem() instanceof ITotem) {
            if (this.item.getTag() != null) {
                int Soulcount = this.item.getTag().getInt(ITotem.SOULS_AMOUNT);
                if (!this.item.isEmpty()) {
                    if (Soulcount > 0) {
                        Soulcount -= souls;
                        this.item.getTag().putInt(ITotem.SOULS_AMOUNT, Soulcount);
                        this.generateParticles();
                    }
                }
            }
        }
        if (this.level != null) {
            Player player = this.getOwner();
            if (player != null) {
                if (SEHelper.getSEActive(player)) {
                    int Soulcount = SEHelper.getSESouls(player);
                    if (Soulcount > 0) {
                        SEHelper.decreaseSoulsNoDiscount(player, souls);
                        ArcaBlockEntity arcaTile = (ArcaBlockEntity) this.level.getBlockEntity(SEHelper.getArcaBlock(player));
                        if (arcaTile != null) {
                            arcaTile.generateParticles();
                            this.generateParticles();
                        }
                    }
                }
            }
        }
        this.markUpdated();

    }

    public int getSpinning(){
        return this.spinning;
    }

    public void generateParticles() {
        if (this.getSouls() <= 0){
            return;
        }
        BlockPos blockpos = this.getBlockPos();

        if (this.level != null) {
            if (!this.level.isClientSide) {
                ServerLevel serverWorld = (ServerLevel) this.level;
                double d0 = (double) blockpos.getX() + this.level.random.nextDouble();
                double d1 = (double) blockpos.getY() + this.level.random.nextDouble();
                double d2 = (double) blockpos.getZ() + this.level.random.nextDouble();
                for (int p = 0; p < 4; ++p) {
                    serverWorld.sendParticles(ParticleTypes.SOUL_FIRE_FLAME, d0, d1, d2, 1, 0, 0, 0, 0);
                    serverWorld.sendParticles(ParticleTypes.SMOKE, d0, d1, d2, 1, 0.0D, 5.0E-4D, 0.0D, 5.0E-4D);
                }
            }
            this.spinning = 20;
        }
    }

    public void generateManyParticles(){
        BlockPos blockpos = this.getBlockPos();
        if (this.level != null) {
            if (!this.level.isClientSide) {
                ServerLevel serverWorld = (ServerLevel) this.level;
                for(int k = 0; k < 20; ++k) {
                    double d9 = (double)blockpos.getX() + 0.5D + (this.level.random.nextDouble() - 0.5D) * 2.0D;
                    double d13 = (double)blockpos.getY() + 0.5D + (this.level.random.nextDouble() - 0.5D) * 2.0D;
                    double d19 = (double)blockpos.getZ() + 0.5D + (this.level.random.nextDouble() - 0.5D) * 2.0D;
                    serverWorld.sendParticles(ParticleTypes.SMOKE, d9, d13, d19, 1, 0.0D, 0.0D, 0.0D, 0);
                    serverWorld.sendParticles(ParticleTypes.SOUL_FIRE_FLAME, d9, d13, d19, 1, 0.0D, 0.0D, 0.0D, 0);
                }
            }
        }

    }

    @Override
    public CompoundTag getUpdateTag() {
        return this.writeNetwork(super.getUpdateTag());
    }

    @Override
    public void onDataPacket(Connection net, ClientboundBlockEntityDataPacket pkt) {
        this.readNetwork(pkt.getTag());
    }

    @Override
    public void handleUpdateTag(CompoundTag tag) {
        super.load(tag);
        this.readNetwork(tag);
    }

    public void readNetwork(CompoundTag tag) {
        item = ItemStack.of(tag.getCompound("item"));
    }

    public CompoundTag writeNetwork(CompoundTag tag) {
        tag.put("item", item.save(new CompoundTag()));
        return tag;
    }

    public void clearContent() {
        this.setItem(ItemStack.EMPTY);
    }

    public void tick() {
        if (this.spinning > 0){
            --this.spinning;
        }
    }

    public void markUpdated() {
        this.setChanged();
        this.getLevel().sendBlockUpdated(this.getBlockPos(), this.getBlockState(), this.getBlockState(), 3);
    }
}

package com.Polarice3.Goety.common.blocks.entities;

import com.Polarice3.Goety.client.particles.PortalShockwaveParticleOption;
import com.Polarice3.Goety.config.MainConfig;
import com.Polarice3.Goety.utils.MathHelper;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.Lists;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.network.protocol.game.ClientboundSetTimePacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.GameRules;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.phys.AABB;

import java.util.List;

public class NightBeaconBlockEntity extends ChunkLoadBlockEntity {
    List<BeaconBeamSection> beamSections = Lists.newArrayList();
    private List<BeaconBeamSection> checkingBeamSections = Lists.newArrayList();
    private boolean daylightTrue;
    private boolean isNight;
    private boolean hasPortal;
    private boolean isActive;
    private int lastCheckY;

    public NightBeaconBlockEntity(BlockPos p_155229_, BlockState p_155230_) {
        super(ModBlockEntities.NIGHT_BEACON.get(), p_155229_, p_155230_);
    }

    @Override
    public boolean shouldChunkLoad() {
        return this.isActive && !this.beamSections.isEmpty();
    }

    public static void tick(Level p_155108_, BlockPos p_155109_, BlockState p_155110_, NightBeaconBlockEntity p_155111_) {
        p_155111_.chunkLoadBlock();
        int i = p_155109_.getX();
        int j = p_155109_.getY();
        int k = p_155109_.getZ();
        BlockPos blockpos;
        if (p_155111_.lastCheckY < j) {
            blockpos = p_155109_;
            p_155111_.checkingBeamSections = Lists.newArrayList();
            p_155111_.lastCheckY = p_155109_.getY() - 1;
        } else {
            blockpos = new BlockPos(i, p_155111_.lastCheckY + 1, k);
        }

        BeaconBeamSection beaconblockentity$beaconbeamsection = p_155111_.checkingBeamSections.isEmpty() ? null : p_155111_.checkingBeamSections.get(p_155111_.checkingBeamSections.size() - 1);
        int l = p_155108_.getHeight(Heightmap.Types.WORLD_SURFACE, i, k);

        for(int i1 = 0; i1 < 10 && blockpos.getY() <= l; ++i1) {
            BlockState blockstate = p_155108_.getBlockState(blockpos);
            float[] afloat = blockstate.getBeaconColorMultiplier(p_155108_, blockpos, p_155109_);
            if (afloat != null) {
                if (p_155111_.checkingBeamSections.size() <= 1) {
                    beaconblockentity$beaconbeamsection = new BeaconBeamSection();
                    p_155111_.checkingBeamSections.add(beaconblockentity$beaconbeamsection);
                } else if (beaconblockentity$beaconbeamsection != null) {
                    beaconblockentity$beaconbeamsection.increaseHeight();
                }
            } else {
                if (beaconblockentity$beaconbeamsection == null || blockstate.getLightBlock(p_155108_, blockpos) >= 15 && !blockstate.is(Blocks.BEDROCK)) {
                    p_155111_.checkingBeamSections.clear();
                    p_155111_.lastCheckY = l;
                    break;
                }

                beaconblockentity$beaconbeamsection.increaseHeight();
            }

            blockpos = blockpos.above();
            ++p_155111_.lastCheckY;
        }

        if (p_155108_.getGameTime() % 20L == 0L){
            if (!p_155111_.beamSections.isEmpty()) {
                p_155111_.hasPortal = hasPortal(p_155108_, p_155109_);
            }
        }

        if (p_155108_.getGameTime() % 80L == 0L) {
            if (p_155111_.isActive && !p_155111_.beamSections.isEmpty()) {
                playSound(p_155108_, p_155109_, SoundEvents.BEACON_AMBIENT);
            }
        }

        if (p_155108_.getServer() != null) {
            if (p_155111_.isActive && !p_155111_.beamSections.isEmpty()) {
                for (ServerLevel serverLevel : p_155108_.getServer().getAllLevels()) {
                    long currentDay = serverLevel.getDayTime() / 24000L;
                    if (currentDay % 8 != 0){
                        currentDay += 1;
                    }
                    serverLevel.setDayTime(MathHelper.setDayNumberAndTime(currentDay, 18000));
                    for (ServerPlayer player : serverLevel.players()) {
                        player.connection.send(new ClientboundSetTimePacket(serverLevel.getGameTime(), serverLevel.getDayTime(), serverLevel.getGameRules().getBoolean(GameRules.RULE_DAYLIGHT)));
                    }
                }
            }
        }

        if (p_155111_.lastCheckY >= l) {
            p_155111_.lastCheckY = p_155108_.getMinBuildHeight() - 1;
            p_155111_.beamSections = p_155111_.checkingBeamSections;
        }

        if (!p_155108_.isClientSide && p_155108_ instanceof ServerLevel serverLevel) {
            if (!p_155111_.isActive && !serverLevel.dimensionType().hasFixedTime() && !p_155111_.getBeamSections().isEmpty()) {
                playSound(p_155108_, p_155109_, SoundEvents.BEACON_ACTIVATE);
                serverLevel.sendParticles(new PortalShockwaveParticleOption(), i + 0.5F, j, k + 0.5F, 0, 0, 0, 0, 0);
                p_155111_.isActive = true;
            } else if (p_155111_.isActive && p_155111_.getBeamSections().isEmpty()){
                playSound(p_155108_, p_155109_, SoundEvents.BEACON_DEACTIVATE);
                p_155111_.isActive = false;
            }
        }
    }

    private static boolean hasPortal(Level level, BlockPos blockPos){
        return level.getBlockState(blockPos.below().below()).is(Blocks.NETHER_PORTAL) && MainConfig.EnableNightBeacon.get();
    }

    public void setDayLight(boolean daylightTrue){
        this.daylightTrue = daylightTrue;
    }

    public void setRemoved() {
        if (this.level != null) {
            playSound(this.level, this.worldPosition, SoundEvents.BEACON_DEACTIVATE);
            if (MainConfig.EnableNightBeacon.get()) {
                if (this.level.getServer() != null && this.isActive && !this.beamSections.isEmpty()) {
                    for (ServerLevel serverLevel : this.level.getServer().getAllLevels()) {
                        long currentDay = serverLevel.getDayTime() / 24000L;
                        serverLevel.setDayTime(MathHelper.setDayNumberAndTime(currentDay, 23000));
                        for (ServerPlayer player : serverLevel.players()) {
                            player.connection.send(new ClientboundSetTimePacket(serverLevel.getGameTime(), serverLevel.getDayTime(), serverLevel.getGameRules().getBoolean(GameRules.RULE_DAYLIGHT)));
                        }
                    }
                }
            }
        }
        super.setRemoved();
    }

    public static void playSound(Level p_155104_, BlockPos p_155105_, SoundEvent p_155106_) {
        p_155104_.playSound((Player)null, p_155105_, p_155106_, SoundSource.BLOCKS, 1.0F, 1.0F);
    }

    public List<BeaconBeamSection> getBeamSections() {
        return !this.hasPortal ? ImmutableList.of() : this.beamSections;
    }

    public void load(CompoundTag p_155113_) {
        super.load(p_155113_);
        this.daylightTrue = p_155113_.getBoolean("daylightTrue");
        this.isNight = p_155113_.getBoolean("isNight");
        this.hasPortal = p_155113_.getBoolean("hasPortal");
        this.isActive = p_155113_.getBoolean("isActive");
    }

    protected void saveAdditional(CompoundTag p_187463_) {
        super.saveAdditional(p_187463_);
        p_187463_.putBoolean("daylightTrue", this.daylightTrue);
