                .encodeStart(NbtOps.INSTANCE, this.voidSpawner)
                .get()
                .ifLeft(tag -> compoundTag.merge((CompoundTag)tag))
                .ifRight(param0x -> Goety.LOGGER.warn("Failed to encode VoidSpawner {}", param0x.message()));
    }

