            double e = i >= 2 ? listTag.getDouble(1) : blockPos.getY() + randomSource.nextInt(3) - 1;
            double f = i >= 3 ? listTag.getDouble(2) : blockPos.getZ() + (randomSource.nextDouble() - randomSource.nextDouble()) * this.config.spawnRange() + 0.5;
