            double f = blockPos.getZ() + 0.5D + (randomSource.nextDouble() - 0.5D) * 2.0D;
            level.sendParticles(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), d, e, f, 1, 0.0D, 0.0D, 0.0D, 0.0F);
            level.sendParticles(ModParticleTypes.END_FIRE.get(), d, e, f, 1, 0.0D, 0.0D, 0.0D, 0.0F);
            level.sendParticles(ModParticleTypes.END_FIRE_DROP.get(), d, e, f, 1, 0.0D, 0.0D, 0.0D, 0.0F);
        }
    }

    public static void addDetectPlayerParticles(ServerLevel level, BlockPos blockPos, RandomSource randomSource, int i) {
        for (int j = 0; j < 30 + Math.min(i, 10) * 5; j++) {
            double d = (2.0F * randomSource.nextFloat() - 1.0F) * 0.65D;
            double e = (2.0F * randomSource.nextFloat() - 1.0F) * 0.65D;
            double f = blockPos.getX() + 0.5D + d;
            double g = blockPos.getY() + 0.1D + randomSource.nextFloat() * 0.8D;
            double h = blockPos.getZ() + 0.5D + e;
            level.sendParticles(ModParticleTypes.VOID_SPAWNER_DETECTION.get(), f, g, h, 1, 0.0D, 0.0D, 0.0D, 0.0F);
        }
    }

    public static void addEjectItemParticles(ServerLevel level, BlockPos blockPos, RandomSource randomSource) {
        for (int i = 0; i < 20; i++) {
            double d = blockPos.getX() + 0.4D + randomSource.nextDouble() * 0.2D;
            double e = blockPos.getY() + 0.4D + randomSource.nextDouble() * 0.2D;
            double f = blockPos.getZ() + 0.4D + randomSource.nextDouble() * 0.2D;
            double g = randomSource.nextGaussian() * 0.02D;
            double h = randomSource.nextGaussian() * 0.02D;
            double j = randomSource.nextGaussian() * 0.02D;
            level.sendParticles(ModParticleTypes.SMALL_END_FIRE.get(), d, e, f, 0, g, h, j * 0.25D, 0.5F);
            level.sendParticles(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), d, e, f, 0, g, h, j, 0.5F);
        }
    }

    public interface StateAccessor {
        void setState(Level level, VoidSpawnerState trialSpawnerState);

        VoidSpawnerState getState();

        void markUpdated();
    }
}

package com.Polarice3.Goety.common.blocks.entities.void_spawner;

import com.Polarice3.Goety.init.ModSounds;
import com.Polarice3.Goety.utils.ModUUIDUtil;
import com.google.common.collect.Sets;
import com.mojang.serialization.Codec;
import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.Util;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.RandomSource;
import net.minecraft.util.random.SimpleWeightedRandomList;
import net.minecraft.util.random.WeightedEntry;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.SpawnData;
import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.function.Function;

public class VoidSpawnerData {
    public static final String TAG_SPAWN_DATA = "spawn_data";
    private static final String TAG_NEXT_MOB_SPAWNS_AT = "next_mob_spawns_at";
    public static MapCodec<VoidSpawnerData> MAP_CODEC = RecordCodecBuilder.mapCodec(
            instance -> instance.group(
                            ModUUIDUtil.CODEC_SET.optionalFieldOf("registered_players", Sets.<UUID>newHashSet()).forGetter(trialSpawnerData -> trialSpawnerData.detectedPlayers),
                            ModUUIDUtil.CODEC_SET.optionalFieldOf("current_mobs", Sets.<UUID>newHashSet()).forGetter(trialSpawnerData -> trialSpawnerData.currentMobs),
                            Codec.LONG.optionalFieldOf("cooldown_ends_at", 0L).forGetter(trialSpawnerData -> trialSpawnerData.cooldownEndsAt),
                            Codec.LONG.optionalFieldOf("next_mob_spawns_at", 0L).forGetter(trialSpawnerData -> trialSpawnerData.nextMobSpawnsAt),
                            Codec.intRange(0, Integer.MAX_VALUE).optionalFieldOf("total_mobs_spawned", 0).forGetter(trialSpawnerData -> trialSpawnerData.totalMobsSpawned),
                            SpawnData.CODEC.optionalFieldOf("spawn_data").forGetter(trialSpawnerData -> trialSpawnerData.nextSpawnData),
                            ResourceLocation.CODEC.optionalFieldOf("ejecting_loot_table").forGetter(trialSpawnerData -> trialSpawnerData.ejectingLootTable)
                    )
                    .apply(instance, VoidSpawnerData::new)
    );
    protected final Set<UUID> detectedPlayers = new HashSet<>();
    protected final Set<UUID> currentMobs = new HashSet<>();
    protected long cooldownEndsAt;
    protected long nextMobSpawnsAt;
    protected int totalMobsSpawned;
    protected Optional<SpawnData> nextSpawnData;
    protected Optional<ResourceLocation> ejectingLootTable;
    protected SimpleWeightedRandomList<SpawnData> spawnPotentials;
    @Nullable
    protected Entity displayEntity;
    protected double spin;
    protected double oSpin;

    public VoidSpawnerData() {
        this(Collections.emptySet(), Collections.emptySet(), 0L, 0L, 0, Optional.empty(), Optional.empty());
    }

    public VoidSpawnerData(Set<UUID> set, Set<UUID> set2, long l, long m, int i, Optional<SpawnData> optional, Optional<ResourceLocation> optional2) {
        this.detectedPlayers.addAll(set);
        this.currentMobs.addAll(set2);
        this.cooldownEndsAt = l;
        this.nextMobSpawnsAt = m;
        this.totalMobsSpawned = i;
        this.nextSpawnData = optional;
        this.ejectingLootTable = optional2;
    }

    public void setSpawnPotentialsFromConfig(VoidSpawnerConfig trialSpawnerConfig) {
        SimpleWeightedRandomList<SpawnData> simpleWeightedRandomList = trialSpawnerConfig.spawnPotentialsDefinition();
        if (simpleWeightedRandomList.isEmpty()) {
            this.spawnPotentials = SimpleWeightedRandomList.single(this.nextSpawnData.orElseGet(SpawnData::new));
        } else {
            this.spawnPotentials = simpleWeightedRandomList;
        }
    }

    public void reset() {
        this.detectedPlayers.clear();
        this.totalMobsSpawned = 0;
        this.nextMobSpawnsAt = 0L;
        this.cooldownEndsAt = 0L;
        this.currentMobs.clear();
    }

    public boolean hasMobToSpawn() {
        boolean bl = this.nextSpawnData.isPresent() && ((SpawnData)this.nextSpawnData.get()).getEntityToSpawn().contains("id", 8);
        return bl || !this.spawnPotentials.isEmpty();
    }

    public boolean hasFinishedSpawningAllMobs(VoidSpawnerConfig trialSpawnerConfig, int i) {
        return this.totalMobsSpawned >= trialSpawnerConfig.calculateTargetTotalMobs(i);
    }

    public boolean haveAllCurrentMobsDied() {
        return this.currentMobs.isEmpty();
    }

    public boolean isReadyToSpawnNextMob(ServerLevel serverLevel, VoidSpawnerConfig trialSpawnerConfig, int i) {
        return serverLevel.getGameTime() >= this.nextMobSpawnsAt && this.currentMobs.size() < trialSpawnerConfig.calculateTargetSimultaneousMobs(i);
    }

    public int countAdditionalPlayers(BlockPos blockPos) {
        if (this.detectedPlayers.isEmpty()) {
            Util.logAndPauseIfInIde("Void Spawner at " + blockPos + " has no detected players");
        }

        return Math.max(0, this.detectedPlayers.size() - 1);
    }

    public void tryDetectPlayers(ServerLevel serverLevel, BlockPos blockPos, VoidSpawner voidSpawner) {
        List<UUID> list = voidSpawner.getPlayerDetector().detect(serverLevel, voidSpawner.getEntitySelector(), blockPos, voidSpawner.getRequiredPlayerRange(), true);
        boolean bl = this.detectedPlayers.addAll(list);
        if (bl) {
            this.nextMobSpawnsAt = Math.max(serverLevel.getGameTime() + 40L, this.nextMobSpawnsAt);
            serverLevel.playSound(null, blockPos, ModSounds.VOID_SPAWNER_DETECT_PLAYER.get(), SoundSource.BLOCKS, 1.0F, (serverLevel.getRandom().nextFloat() - serverLevel.getRandom().nextFloat()) * 0.2F + 1.0F);
            VoidSpawner.addDetectPlayerParticles(serverLevel, blockPos, serverLevel.getRandom(), this.detectedPlayers.size());
        }
    }

    public boolean isReadyToOpenShutter(ServerLevel serverLevel, VoidSpawnerConfig trialSpawnerConfig, float f) {
        long l = this.cooldownEndsAt - trialSpawnerConfig.targetCooldownLength();
        return (float)serverLevel.getGameTime() >= (float)l + f;
    }

    public boolean isReadyToEjectItems(ServerLevel serverLevel, VoidSpawnerConfig trialSpawnerConfig, float f) {
        long l = this.cooldownEndsAt - trialSpawnerConfig.targetCooldownLength();
        return (float)(serverLevel.getGameTime() - l) % f == 0.0F;
    }

    public boolean isCooldownFinished(ServerLevel serverLevel) {
        return serverLevel.getGameTime() >= this.cooldownEndsAt;
    }

    public void setEntityId(VoidSpawner trialSpawner, RandomSource randomSource, EntityType<?> entityType) {
        this.getOrCreateNextSpawnData(trialSpawner, randomSource).getEntityToSpawn().putString("id", BuiltInRegistries.ENTITY_TYPE.getKey(entityType).toString());
    }

    protected SpawnData getOrCreateNextSpawnData(VoidSpawner trialSpawner, RandomSource randomSource) {
        if (this.nextSpawnData.isPresent()) {
            return this.nextSpawnData.get();
        } else {
            this.nextSpawnData = Optional.of(this.spawnPotentials.getRandom(randomSource).map(WeightedEntry.Wrapper::getData).orElseGet(SpawnData::new));
            trialSpawner.markUpdated();
            return this.nextSpawnData.get();
        }
    }

    @Nullable
    public Entity getOrCreateDisplayEntity(VoidSpawner trialSpawner, Level level, VoidSpawnerState trialSpawnerState) {
        if (trialSpawner.canSpawnInLevel(level) && trialSpawnerState.hasSpinningMob()) {
            if (this.displayEntity == null) {
                CompoundTag compoundTag = this.getOrCreateNextSpawnData(trialSpawner, level.getRandom()).getEntityToSpawn();
                if (compoundTag.contains("id", 8)) {
                    this.displayEntity = EntityType.loadEntityRecursive(compoundTag, level, Function.identity());
                }
            }

            return this.displayEntity;
        } else {
            return null;
        }
    }

    public CompoundTag getUpdateTag(VoidSpawnerState trialSpawnerState) {
        CompoundTag compoundTag = new CompoundTag();
        if (trialSpawnerState == VoidSpawnerState.ACTIVE) {
            compoundTag.putLong("next_mob_spawns_at", this.nextMobSpawnsAt);
        }

        this.nextSpawnData.ifPresent(
                spawnData -> compoundTag.put(
                        "spawn_data",
                        SpawnData.CODEC.encodeStart(NbtOps.INSTANCE, spawnData)
                                .result()
                                .orElseThrow(() -> new IllegalStateException("Invalid SpawnData"))
                )
        );
        return compoundTag;
    }

    public double getSpin() {
        return this.spin;
    }

    public double getOSpin() {
        return this.oSpin;
    }
}

package com.Polarice3.Goety.common.blocks.entities.void_spawner;

import com.Polarice3.Goety.client.particles.MagicAshSmokeParticleOption;
import com.Polarice3.Goety.client.particles.ModParticleTypes;
import com.Polarice3.Goety.init.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.util.RandomSource;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;

import java.util.Optional;

public enum VoidSpawnerState implements StringRepresentable {
    INACTIVE("inactive", 0, ParticleEmission.NONE, -1.0, false),
    WAITING_FOR_PLAYERS("waiting_for_players", 4, ParticleEmission.SMALL_FLAMES, 200.0, true),
    ACTIVE("active", 8, ParticleEmission.FLAMES_AND_SMOKE, 1000.0, true),
    WAITING_FOR_REWARD_EJECTION("waiting_for_reward_ejection", 8, ParticleEmission.SMALL_FLAMES, -1.0, false),
    EJECTING_REWARD("ejecting_reward", 8, ParticleEmission.SMALL_FLAMES, -1.0, false),
    COOLDOWN("cooldown", 0, ParticleEmission.SMOKE_INSIDE_AND_TOP_FACE, -1.0, false);

    private static final float DELAY_BEFORE_EJECT_AFTER_KILLING_LAST_MOB = 40.0F;
    private static final int TIME_BETWEEN_EACH_EJECTION = Mth.floor(30.0F);
    private final String name;
    private final int lightLevel;
    private final double spinningMobSpeed;
    private final ParticleEmission particleEmission;
    private final boolean isCapableOfSpawning;

    private VoidSpawnerState(String string2, int j, ParticleEmission particleEmission, double d, boolean bl) {
        this.name = string2;
        this.lightLevel = j;
        this.particleEmission = particleEmission;
        this.spinningMobSpeed = d;
        this.isCapableOfSpawning = bl;
    }

    VoidSpawnerState tickAndGetNext(BlockPos blockPos, VoidSpawner spawner, ServerLevel serverLevel) {
        VoidSpawnerData data = spawner.getData();
        VoidSpawnerConfig config = spawner.getConfig();
        VoidSpawnerState state;
        switch(this) {
            case INACTIVE:
                state = data.getOrCreateDisplayEntity(spawner, serverLevel, WAITING_FOR_PLAYERS) == null ? this : WAITING_FOR_PLAYERS;
                break;
            case WAITING_FOR_PLAYERS:
                if (!data.hasMobToSpawn()) {
                    state = INACTIVE;
                } else {
                    data.tryDetectPlayers(serverLevel, blockPos, spawner);
                    state = data.detectedPlayers.isEmpty() ? this : ACTIVE;
                }
                break;
            case ACTIVE:
                if (!data.hasMobToSpawn()) {
                    state = INACTIVE;
                } else {
                    int i = data.countAdditionalPlayers(blockPos);
                    data.tryDetectPlayers(serverLevel, blockPos, spawner);
                    if (data.hasFinishedSpawningAllMobs(config, i)) {
                        if (data.haveAllCurrentMobsDied()) {
                            data.cooldownEndsAt = serverLevel.getGameTime() + (long)config.targetCooldownLength();
                            data.totalMobsSpawned = 0;
                            data.nextMobSpawnsAt = 0L;
                            state = WAITING_FOR_REWARD_EJECTION;
                            break;
                        }
                    } else if (data.isReadyToSpawnNextMob(serverLevel, config, i)) {
                        spawner.spawnMob(serverLevel, blockPos).ifPresent(uuid -> {
                            data.currentMobs.add(uuid);
                            ++data.totalMobsSpawned;
                            data.nextMobSpawnsAt = serverLevel.getGameTime() + (long)config.ticksBetweenSpawn();
                            data.spawnPotentials.getRandom(serverLevel.getRandom()).ifPresent(data1 -> {
                                data.nextSpawnData = Optional.of(data1.getData());
                                spawner.markUpdated();
                            });
                        });
                    }

                    state = this;
                }
                break;
            case WAITING_FOR_REWARD_EJECTION:
                if (data.isReadyToOpenShutter(serverLevel, config, 40.0F)) {
                    serverLevel.playSound(null, blockPos, ModSounds.VOID_SPAWNER_OPEN_SHUTTER.get(), SoundSource.BLOCKS);
                    state = EJECTING_REWARD;
                } else {
                    state = this;
                }
                break;
            case EJECTING_REWARD:
                if (!data.isReadyToEjectItems(serverLevel, config, (float)TIME_BETWEEN_EACH_EJECTION)) {
                    state = this;
                } else if (data.detectedPlayers.isEmpty()) {
                    serverLevel.playSound(null, blockPos, ModSounds.VOID_SPAWNER_CLOSE_SHUTTER.get(), SoundSource.BLOCKS);
                    data.ejectingLootTable = Optional.empty();
                    state = COOLDOWN;
                } else {
                    if (data.ejectingLootTable.isEmpty()) {
                        data.ejectingLootTable = config.lootTablesToEject().getRandomValue(serverLevel.getRandom());
                    }

                    data.ejectingLootTable.ifPresent(location -> spawner.ejectReward(serverLevel, blockPos, location));
                    data.detectedPlayers.remove(data.detectedPlayers.iterator().next());
                    state = this;
                }
                break;
            case COOLDOWN:
                if (data.isCooldownFinished(serverLevel)) {
                    data.cooldownEndsAt = 0L;
                    state = WAITING_FOR_PLAYERS;
                } else {
                    state = this;
                }
                break;
            default:
                state = INACTIVE;
        }

        return state;
    }

    public int lightLevel() {
        return this.lightLevel;
    }

    public double spinningMobSpeed() {
        return this.spinningMobSpeed;
    }

    public boolean hasSpinningMob() {
        return this.spinningMobSpeed >= 0.0;
    }

    public boolean isCapableOfSpawning() {
        return this.isCapableOfSpawning;
    }

    public void emitParticles(Level level, BlockPos blockPos) {
        this.particleEmission.emit(level, level.getRandom(), blockPos);
    }

    @Override
    public String getSerializedName() {
        return this.name;
    }

    static class LightLevel {
        private static final int UNLIT = 0;
        private static final int HALF_LIT = 4;
        private static final int LIT = 8;

        private LightLevel() {
        }
    }

    interface ParticleEmission {
        ParticleEmission NONE = (level, randomSource, blockPos) -> {};
        ParticleEmission SMALL_FLAMES = (level, randomSource, blockPos) -> {
            if (randomSource.nextInt(2) == 0) {
                Vec3 vec3 = blockPos.getCenter().offsetRandom(randomSource, 0.9F);
                addParticle(ModParticleTypes.SMALL_END_FIRE.get(), vec3, level);
            }
        };
        ParticleEmission FLAMES_AND_SMOKE = (level, randomSource, blockPos) -> {
            Vec3 vec3 = blockPos.getCenter().offsetRandom(randomSource, 1.0F);
            addParticle(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec3, level);
            addParticle(ModParticleTypes.END_FIRE.get(), vec3, level);
            addParticle(ModParticleTypes.END_FIRE_DROP.get(), vec3, level);
        };
        ParticleEmission SMOKE_INSIDE_AND_TOP_FACE = (level, randomSource, blockPos) -> {
            Vec3 vec3 = blockPos.getCenter().offsetRandom(randomSource, 0.9F);
            if (randomSource.nextInt(3) == 0) {
                addParticle(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec3, level);
            }

            if (level.getGameTime() % 20L == 0L) {
                Vec3 vec32 = blockPos.getCenter().add(0.0, 0.5, 0.0);
                int i = level.getRandom().nextInt(4) + 20;

                for (int j = 0; j < i; j++) {
                    addParticle(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec32, level);
                }
            }
        };

        private static void addParticle(ParticleOptions particleOptions, Vec3 vec3, Level level) {
            level.addParticle(particleOptions, vec3.x(), vec3.y(), vec3.z(), 0.0, 0.0, 0.0);
        }

        void emit(Level level, RandomSource randomSource, BlockPos blockPos);
    }

    static class SpinningMob {
        private static final double NONE = -1.0;
        private static final double SLOW = 200.0;
        private static final double FAST = 1000.0;

        private SpinningMob() {
        }
    }
}

